        os.path.join(SRC, p["id"] + ".java") for p in probes))
    pr = subprocess.Popen(["java", "-cp", ".", "JDrv", lst],
                          stdout=subprocess.PIPE, text=True, cwd=drv)
    n = 0; t0 = time.time()
    for line in pr.stdout:
        line = line.strip()
        if "|" not in line: continue
        pid, v = line.split("|", 1)
        if pid == "__TOTAL_MS__": print("inner " + line); continue
        verdicts[pid] = v; emit(pid, v, "")
        n += 1
        if n % 1000 == 0:
            el = time.time()-t0
            print("[progress] java [%d/%d] elapsed %s ETA %s mean %.2f ms"
                  % (n, len(probes), hms(el),
                     hms(el/n*(len(probes)-n)), 1000.0*el/n))
            sys.stdout.flush()
    pr.wait()

elif MODE == "ts_inproc":
    drv = os.path.join(ROOT, "drv"); os.makedirs(drv, exist_ok=True)
    open(os.path.join(drv, "tdrv.js"), "w").write(r'''// ROUTE A1 for typescript: the require-able checker inside the SHIPPED
// typescript.js.  A chunk of probe files becomes one ts.Program and each
// file's own syntactic + semantic diagnostics are read back; the lib
// files are parsed once and cached, which is what makes it cheap.
const fs = require('fs');
const path = require('path');
const TSJS = '/persist/tv/ts5/node_modules/typescript/lib/typescript.js';
const ts = require(TSJS);
console.log('__NOTE__|typescript ' + ts.version + ' from ' + TSJS);
const files = fs.readFileSync(process.argv[2], 'utf8')
                .split('\n').filter(s => s.length > 0);
const opts = {
  target: ts.ScriptTarget.ES2022,
  strict: true,
  noEmit: true,
  skipLibCheck: true,
  types: [],
  moduleResolution: ts.ModuleResolutionKind.NodeJs,
};
const base = ts.createCompilerHost(opts);
const libCache = new Map();
const host = Object.create(base);
host.writeFile = () => {};
host.getSourceFile = function (fn, lv, oe, sfc) {
  if (libCache.has(fn)) return libCache.get(fn);
  const sf = base.getSourceFile(fn, lv, oe, sfc);
  if (/lib\..*\.d\.ts$/.test(fn)) libCache.set(fn, sf);
  return sf;
};
const CH = 500;
const t0 = Date.now();
let n = 0;
for (let i = 0; i < files.length; i += CH) {
  const chunk = files.slice(i, i + CH);
  const program = ts.createProgram(chunk, opts, host);
  for (const f of chunk) {
    const sf = program.getSourceFile(f);
    let ok;
    if (!sf) { ok = false; }
    else {
      const d = program.getSyntacticDiagnostics(sf)
                .concat(program.getSemanticDiagnostics(sf));
      ok = d.length === 0;
    }
    const b = path.basename(f).replace(/\.ts$/, '');
    console.log(b + '|' + (ok ? 'ACCEPT' : 'REFUSE'));
    n++;
  }
}
console.log('__TOTAL_MS__|' + (Date.now() - t0) + '|' + n);
''')
    lst = os.path.join(drv, "list.txt")
    open(lst, "w").write("\n".join(
        os.path.join(SRC, p["id"] + ".ts") for p in probes))
    pr = subprocess.Popen(["node", "--max-old-space-size=3000",
                           "tdrv.js", lst],
                          stdout=subprocess.PIPE, text=True, cwd=drv)
    n = 0; t0 = time.time()
    for line in pr.stdout:
        line = line.strip()
        if "|" not in line: continue
        pid, v = line.split("|", 1)
        if pid == "__TOTAL_MS__": print("inner " + line); continue
        if pid == "__NOTE__": print("inner " + line); sys.stdout.flush(); continue
        verdicts[pid] = v; emit(pid, v, "")
        n += 1
        if n % 500 == 0:
            el = time.time()-t0
            print("[progress] typescript [%d/%d] elapsed %s ETA %s mean %.2f ms"
                  % (n, len(probes), hms(el),
                     hms(el/n*(len(probes)-n)), 1000.0*el/n))
            sys.stdout.flush()
    pr.wait()

el = time.time()-t_start
acc = sum(1 for v in verdicts.values() if v == "ACCEPT")
print("== %s: %d probes, %d ACCEPT, %d REFUSE, %d missing, %.1f s, %.1f ms/probe"
      % (LANG, len(probes), acc, len(verdicts)-acc,
         len(probes)-len(verdicts), el,
         1000.0*el/len(probes) if probes else 0))
out.write("__SUMMARY__|%d|%d|%d|%.3f\n"
          % (len(probes), acc, len(verdicts)-acc, el))
out.close()
PY_EOF
echo "=== acceptance lane java done ==="
date -u +%Y-%m-%dT%H:%M:%SZ
